// Terrain generation — deterministic from the world seed. The 256x256
// tile map is generated by a pure function (not a shipped JSON asset),
// so the client and the server always derive the identical map from the
// same seed. Terrain grid is a Uint8Array of TERRAIN_CODE values,
// row-major: index = ty * size + tx.

import { MAP_TILES, TERRAIN_CODE, TERRAIN_FROM_CODE, type TerrainKind } from '@rust2d/shared';

import { valueNoise } from '../rng';

/** Water below this elevation, rock above this one (see generateTerrain). */
const WATER_LEVEL = 0.3;
const ROCK_LEVEL = 0.74;
/** Moisture above this (and not water/rock) becomes forest. */
const FOREST_MOISTURE = 0.58;
/** Grass clearing radius (tiles) forced around the spawn point (centre). */
const SPAWN_CLEARING_R = 6;

export function generateTerrain(seed: number, size: number = MAP_TILES): Uint8Array {
  const grid = new Uint8Array(size * size);
  for (let ty = 0; ty < size; ty++) {
    for (let tx = 0; tx < size; tx++) {
      // Two-octave elevation: broad hills + finer detail.
      const elevation =
        0.65 * valueNoise(tx, ty, 24, seed) + 0.35 * valueNoise(tx, ty, 96, seed + 101);
      const moisture = valueNoise(tx, ty, 32, seed + 517);
      let kind: TerrainKind = 'grass';
      if (elevation < WATER_LEVEL) kind = 'water';
      else if (elevation > ROCK_LEVEL) kind = 'rock';
      else if (moisture > FOREST_MOISTURE) kind = 'forest';
      grid[ty * size + tx] = TERRAIN_CODE[kind];
    }
  }

  // Spawn clearing: force grass around the map centre so the player
  // never spawns in water or on rock.
  const c = Math.floor(size / 2);
  for (let ty = c - SPAWN_CLEARING_R; ty <= c + SPAWN_CLEARING_R; ty++) {
    for (let tx = c - SPAWN_CLEARING_R; tx <= c + SPAWN_CLEARING_R; tx++) {
      if (tx < 0 || ty < 0 || tx >= size || ty >= size) continue;
      const dx = tx - c;
      const dy = ty - c;
      if (dx * dx + dy * dy <= SPAWN_CLEARING_R * SPAWN_CLEARING_R) {
        grid[ty * size + tx] = TERRAIN_CODE.grass;
      }
    }
  }

  // Water cleanup: isolated single water tiles (no water neighbour)
  // become grass, so lakes read as lakes instead of speckles.
  for (let ty = 0; ty < size; ty++) {
    for (let tx = 0; tx < size; tx++) {
      const i = ty * size + tx;
      if (grid[i] !== TERRAIN_CODE.water) continue;
      let neighbours = 0;
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          if (dx === 0 && dy === 0) continue;
          const nx = tx + dx;
          const ny = ty + dy;
          if (nx < 0 || ny < 0 || nx >= size || ny >= size) continue;
          if (grid[ny * size + nx] === TERRAIN_CODE.water) neighbours++;
        }
      }
      if (neighbours === 0) grid[i] = TERRAIN_CODE.grass;
    }
  }

  return grid;
}

/** Terrain at a tile, or null outside the map (treated as blocked). */
export function tileAt(
  terrain: Uint8Array,
  size: number,
  tx: number,
  ty: number,
): TerrainKind | null {
  if (tx < 0 || ty < 0 || tx >= size || ty >= size) return null;
  return TERRAIN_FROM_CODE[terrain[ty * size + tx]];
}

/** Count tiles per terrain kind — used by tests and the map inspector. */
export function terrainDistribution(terrain: Uint8Array): Record<TerrainKind, number> {
  const counts: Record<TerrainKind, number> = {
    grass: 0,
    forest: 0,
    rock: 0,
    water: 0,
  };
  for (let i = 0; i < terrain.length; i++) {
    counts[TERRAIN_FROM_CODE[terrain[i]]]++;
  }
  return counts;
}
